`timescale 1ns/1ps
module tb_banked_memory_ecc; localparam int BANKS=4,ADDR_W=4,DATA_W=64,BE_W=8,ID_W=8; logic clk=0;always #5 clk=~clk;logic rst_n;logic [BANKS-1:0] valid,wr;logic [BANKS-1:0][ADDR_W-1:0] addr;logic [BANKS-1:0][DATA_W-1:0] wdata;logic [BANKS-1:0][BE_W-1:0] be;logic [BANKS-1:0][ID_W-1:0] txn;logic [BANKS-1:0] rv,corr,uncor;logic [BANKS-1:0][DATA_W-1:0] rdata;logic [BANKS-1:0][ID_W-1:0] rtxn;banked_unified_memory_ecc #(.BANKS(BANKS),.BANK_ADDR_WIDTH(ADDR_W),.DATA_WIDTH(DATA_W),.TXN_ID_WIDTH(ID_W)) dut(.clk,.rst_n,.cmd_valid(valid),.cmd_write(wr),.cmd_addr(addr),.cmd_wdata(wdata),.cmd_be(be),.cmd_txn_id(txn),.rsp_valid(rv),.rsp_rdata(rdata),.rsp_txn_id(rtxn),.rsp_ecc_corrected(corr),.rsp_ecc_uncorrectable(uncor));initial begin rst_n=0;valid='0;wr='0;addr='0;wdata='0;be='0;txn='0;repeat(2)@(posedge clk);rst_n=1;valid[0]=1;wr[0]=1;addr[0]=3;wdata[0]=64'h0123456789abcdef;be[0]='1;txn[0]=8'h21;@(posedge clk);valid='0;valid[0]=1;wr[0]=0;addr[0]=3;@(posedge clk);#1;if(!rv[0])$fatal(1,"No response");if(rdata[0]!==64'h0123456789abcdef)$fatal(1,"Readback mismatch");if(uncor[0])$fatal(1,"Unexpected ECC error");$display("PASS ECC banked memory");$finish;end endmodule
